function ajusteEstandar(txt){
  var t=String(txt||"").trim(); if(!t) return "";
  if(AJUSTE_TRABAJO_LISTA.indexOf(t)>=0) return t;
  for(var i=0;i<AJUSTE_SINON.length;i++) if(AJUSTE_SINON[i][0].test(t)) return AJUSTE_SINON[i][1];
  return "";
}
