/* ─── Auditoría de fotos de limpieza: qué fotos esperadas subió cada formulario.
   Base del análisis de Pareto (Dashboard Ejecutivo) y del refuerzo en el formulario. */
var PROF_PHOTO_KEYS = [
  ["fotosRegadera","Regadera"],
  ["fotosDucha","Ducha y mampara"],
  ["fotosVentanas","Ventanas"],
  ["fotosEstufa","Cocina — estufa"],
  ["fotosFregadero","Cocina — fregadero"],
  ["fotosMicroondas2","Cocina — microondas por dentro"],
  ["fotosPlatos","Cocina — platos y cubiertos"],
  ["fotosGavetas","Gavetas y utensilios"],
  ["fotosDetrasElect","Detrás de electrodomésticos"],
];
function photoFilled(v){
  function one(x){ return !!(x&&typeof x==="string"&&(x.indexOf("http")===0||x.indexOf("data:")===0)); }
  if(Array.isArray(v)) return v.some(one);
  return one(v);
}
/* Lista de fotos ESPERADAS de un formulario de limpieza, cada una con si se subió.
   Solo aplica a limpieza tradicional y profunda. */
function cleaningPhotoAudit(rep, propObj){
  if(!rep) return null;
  var items=[];
  if(rep.categoria==="Limpieza tradicional"){
    var nH=Math.max((rep.fotosHabitaciones||[]).length, propObj?(parseInt(propObj.cuartos,10)||0):0);
    for(var i=0;i<nH;i++) items.push({key:"hab_general",label:"Habitación — foto general",filled:photoFilled((rep.fotosHabitaciones||[])[i])});
    var nB=(rep.fotosBanos||[]).length;
    for(var j=0;j<nB;j++){ var b=rep.fotosBanos[j]||{}; items.push({key:"bano_ducha",label:"Baño — ducha",filled:photoFilled(b.ducha)}); items.push({key:"bano_inodoro",label:"Baño — inodoro",filled:photoFilled(b.inodoro)}); }
    TRAD_SINGLE_PHOTOS.forEach(function(p){ items.push({key:p[0],label:p[1],filled:photoFilled(rep[p[0]])}); });
  } else if(rep.categoria==="Limpieza profunda"){
    PROF_PHOTO_KEYS.forEach(function(p){ items.push({key:p[0],label:p[1],filled:photoFilled(rep[p[0]])}); });
  } else return null;
  return items;
}
/* Agrega la auditoría sobre un conjunto de reportes: qué fotos faltan más y la
   tasa global de subida. vendorMatch(r) limita a un técnico; propsByName da cuartos. */
function fotosPareto(reps, vendorMatch, propsByName){
  var counts={}, forms=0, exp=0, fill=0, sinFoto=0;
  (reps||[]).forEach(function(r){
    if(!r||!isCleaning(r.categoria)) return;
    if(vendorMatch && !vendorMatch(r)) return;
    var po=propsByName?propsByName[normalize(r.propiedad||"")]:null;
    var items=cleaningPhotoAudit(r, po); if(!items||!items.length) return;
    forms++;
    var alguna=false;
    items.forEach(function(it){
      var c=counts[it.key]||(counts[it.key]={label:it.label,missing:0,total:0});
      c.total++; exp++;
      if(it.filled){ fill++; alguna=true; } else c.missing++;
    });
    if(!alguna) sinFoto++;
  });
  var rows=Object.keys(counts).map(function(k){ return Object.assign({key:k},counts[k]); })
    .filter(function(x){ return x.missing>0; })
    .sort(function(a,b){ return b.missing-a.missing; });
  return {rows:rows, forms:forms, exp:exp, fill:fill, sinFoto:sinFoto, pct: exp?Math.round(fill/exp*100):0};
}
/* Tasa de omisión de UNA foto por técnico, y la media del equipo (base de #5). */
function perTechMissRate(allReps, propsByName, key){
  var by={};
  (allReps||[]).forEach(function(r){
    if(!r||!isCleaning(r.categoria)) return;
    var items=cleaningPhotoAudit(r, propsByName?propsByName[normalize(r.propiedad||"")]:null); if(!items) return;
    var em=String(r.reportadoPor||"").toLowerCase(); if(!em) return;
    items.forEach(function(it){ if(it.key!==key) return; var b=by[em]||(by[em]={miss:0,total:0}); b.total++; if(!it.filled) b.miss++; });
  });
  var rates={}, sum=0, n=0;
  Object.keys(by).forEach(function(e){ var b=by[e]; if(b.total<1) return; var rate=b.miss/b.total; rates[e]=rate; sum+=rate; n++; });
  return {byEmail:rates, mean: n?sum/n:0};
}
function verificarFoto(dataUrl){
  return new Promise(function(res){
    try{ var img=new Image(); img.onload=function(){ res({ok:img.naturalWidth>0&&img.naturalHeight>0, w:img.naturalWidth, h:img.naturalHeight}); }; img.onerror=function(){ res({ok:false}); }; img.src=dataUrl; }
    catch(_){ res({ok:false}); }
  });
}
/* Diagnóstico de fotos para el técnico que abre un formulario de limpieza.
   Decide si hay que (verify) pedirle una foto de verificación —muchos formularios
   sin fotos— o (force) forzar la foto #1 del Pareto —la omite más que la media. */
function techPhotoDiag(allReps, vendorEmail, props, category){
  var out={active:false};
  if(category!=="Limpieza tradicional" && category!=="Limpieza profunda") return out;
  var em=String(vendorEmail||"").toLowerCase(); if(!em) return out;
  var propsByName={}; (props||[]).forEach(function(p){ propsByName[normalize(p.name||"")]=p; });
  var mine=fotosPareto(allReps, function(r){ return mismoTecnico(r, em); }, propsByName);
  if(mine.forms===0) return out;
  /* #7 — subida muy baja / formularios sin foto (una vez cada 30 días tras verificar). */
  var verificadoReciente=false;
  try{ var vd=localStorage.getItem("epi_photoverify_"+em); if(vd) verificadoReciente=(Date.now()-parseInt(vd,10))<30*86400000; }catch(_){}
  if(!verificadoReciente && mine.forms>=2 && mine.sinFoto>=2 && mine.pct<50){
    return {active:true, mode:"verify", pct:mine.pct, sinFoto:mine.sinFoto};
  }
  /* #5 — la foto #1 del Pareto del equipo, si este técnico la omite más que la media. */
  var doneToday=false; try{ doneToday=localStorage.getItem("epi_force5_"+em)===todayStr(); }catch(_){}
  if(doneToday) return out;
  var catKeys={}; (category==="Limpieza profunda"?PROF_PHOTO_KEYS:TRAD_SINGLE_PHOTOS).forEach(function(p){ catKeys[p[0]]=p[1]; });
  var team=fotosPareto(allReps, null, propsByName);
  var topRow=(team.rows||[]).filter(function(x){ return catKeys[x.key]; })[0];
  if(!topRow) return out;
  var st=perTechMissRate(allReps, propsByName, topRow.key);
  var myRate=st.byEmail[em];
  if(myRate==null || !(myRate>st.mean)) return out;
  return {active:true, mode:"force", topKey:topRow.key, topLabel:catKeys[topRow.key]||topRow.label};
}


/* ═══ UTILS */
function fmtDate(d) {
  if (!d) return "—";
  try {
    var dt = (typeof d==="string"&&d.length===10&&/^\d{4}-\d{2}-\d{2}$/.test(d))
      ? new Date(d+"T12:00:00")
      : new Date(d);
    if (isNaN(dt.getTime())) return String(d);
    return dt.toLocaleDateString("es-GT",{day:"2-digit",month:"short",year:"numeric"});
  } catch(e) { return String(d)||"—"; }
}
function todayStr() { return new Date().toISOString().split("T")[0]; }
function relDate(days) { return new Date(Date.now()-days*86400000).toISOString().split("T")[0]; }
/* Rangos de período rápido (compartido por todos los filtros). Semanas lunes→domingo. */
function presetRange(val){
  var now=new Date(); now.setHours(12,0,0,0);
  function iso(d){ return d.toISOString().split("T")[0]; }
  var to=iso(now);
  var lunes=new Date(now); lunes.setDate(now.getDate()-((now.getDay()+6)%7)); /* lunes de esta semana */
  if(val==="hoy")        return {from:to,to:to};
  if(val==="semana")     return {from:iso(lunes), to:to};
  if(val==="semana_ant"){ var lAnt=new Date(lunes); lAnt.setDate(lunes.getDate()-7); var dAnt=new Date(lunes); dAnt.setDate(lunes.getDate()-1); return {from:iso(lAnt), to:iso(dAnt)}; }
  if(val==="semanas_ant"){ var dPrev=new Date(lunes); dPrev.setDate(lunes.getDate()-1); return {from:"", to:iso(dPrev)}; } /* todas las semanas antes de la actual */
  if(val==="mes")        return {from:iso(new Date(now.getFullYear(),now.getMonth(),1)), to:to};
  if(val==="3meses"){ var t3=new Date(now); t3.setMonth(t3.getMonth()-3); return {from:iso(t3), to:to}; }
  if(val==="7d")  return {from:relDate(6),  to:to};
  if(val==="14d") return {from:relDate(13), to:to};
  if(val==="30d") return {from:relDate(29), to:to};
  return {from:"", to:""};
}
/* Opciones del menú "Período rápido" — orden y etiquetas uniformes */
var PRESET_OPTS = [
  ["hoy","Hoy"],
  ["semana","Semana en curso"],
  ["semana_ant","Semana anterior"],
  ["mes","Este mes"],
  ["semanas_ant","Semanas anteriores"],
  ["todo","Todo"],
];
function daysSince(ts) { return Math.floor((Date.now()-ts)/86400000); }
var QA_VENTANA_DIAS = 7;
/* Una limpieza que nadie revisó dentro de la ventana. Se cuenta desde la fecha
   del trabajo, no desde que se registró: lo que importa es qué tan viejo es lo
   que se estaría aprobando. Aprobar una limpieza de hace tres semanas no es un
   control de calidad —nadie se acuerda— y firmarla ensucia el historial. */
function qaFueraDeTiempo(r){
  if(!r || !isCleaning(r.categoria)) return false;
  if((r.qaStatus||"pendiente")!=="pendiente") return false;
  var f = String(r.fecha||"").slice(0,10);
  if(!f) return false;
  return SCHED.dias(f, SCHED.hoyGT()) > QA_VENTANA_DIAS;
}

function alertLvl(r) {
  if (r.paid || !r.total || isDanos(r.categoria)) return null;
  var d = daysSince(r.createdAt||r.id);
  if (d>=21) return "red"; if (d>=14) return "orange"; if (d>=7) return "yellow";
  return null;
}
function uniq(arr) { return [...new Set(arr)]; }
var DANIO_VIDEO_MAX_MB = 12;
/* Un video explica en tres segundos lo que tres fotos no: si la gaveta cierra,
   si la fuga gotea, si el ruido viene del motor. Los videos NO se comprimen
   —no hay forma barata en el navegador—, así que el tope se aplica al aceptar
   el archivo: 12 MB dan de sobra para ~15 segundos de teléfono. */
function leerVideo(file){
  return new Promise(function(res, rej){
    var mb = file.size/1048576;
    if(mb > DANIO_VIDEO_MAX_MB){
      rej(new Error("El video pesa "+mb.toFixed(1)+" MB y el máximo es "+DANIO_VIDEO_MAX_MB+" MB. Graba uno más corto, de unos 10 a 15 segundos."));
      return;
    }
    var fr=new FileReader();
    fr.onload=function(ev){ res({data:ev.target.result, name:file.name||"video.mp4", mime:file.type||"video/mp4", mb:mb}); };
    fr.onerror=function(){ rej(new Error("No se pudo leer el video.")); };
    fr.readAsDataURL(file);
  });
}

function VideoDanio({video, onSet}){
  const [err,setErr] = useState("");
  const ref = useRef(null);
  function pick(e){
    var f=e.target.files&&e.target.files[0];
    e.target.value="";
    if(!f) return;
    setErr("");
    leerVideo(f).then(function(v){ onSet(v); }, function(ex){ setErr(ex.message); });
  }
  var yaSubido = video && video.url && !video.data;
  return (
    <div>
      <div style={{fontSize:10,fontWeight:700,color:C.earth,letterSpacing:".14em",textTransform:"uppercase",marginBottom:8}}>
        Video corto <span style={{fontWeight:600,letterSpacing:".04em",textTransform:"none",color:C.taupe}}>· opcional</span>
      </div>
      {(video&&(video.data||video.url))
        ? (
          <div style={{display:"flex",flexDirection:"column",gap:8}}>
            <video src={video.data||video.url} controls playsInline style={{width:"100%",maxHeight:220,borderRadius:12,border:"1px solid "+C.gray,background:"#000",display:"block"}}/>
            <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
              <span style={{fontSize:11,color:C.taupe,fontVariantNumeric:"tabular-nums"}}>{yaSubido?"Guardado":(video.mb?video.mb.toFixed(1)+" MB":"")}</span>
              <button type="button" onClick={function(){onSet(null);setErr("");}} style={{fontSize:11.5,fontWeight:600,color:C.earth,background:"#fff",border:"1px solid "+C.gray,borderRadius:"var(--sa-pill)",padding:"0 15px",minHeight:38,cursor:"pointer",fontFamily:"Montserrat,sans-serif"}}>Quitar video</button>
            </div>
          </div>
        )
        : (
          <button type="button" onClick={function(){ref.current&&ref.current.click();}} style={{width:"100%",border:"2px dashed color-mix(in srgb, "+C.earth+" 31%, transparent)",background:C.surfaceWarm,borderRadius:12,padding:"16px 14px",cursor:"pointer",fontFamily:"Montserrat,sans-serif",color:C.earth,fontSize:12.5,fontWeight:600,display:"flex",flexDirection:"column",alignItems:"center",gap:5}}>
            <span>+ Grabar o subir un video</span>
            <span style={{fontSize:11,fontWeight:400,color:C.taupe,textWrap:"pretty",textAlign:"center",lineHeight:1.5}}>De 10 a 15 segundos, máximo {DANIO_VIDEO_MAX_MB} MB. Para mostrar lo que una foto no explica.</span>
          </button>
        )}
      <input ref={ref} type="file" accept="video/*" style={{display:"none"}} onChange={pick}/>
      {err&&<div style={{marginTop:8,fontSize:11.5,color:C.red,fontWeight:600,lineHeight:1.6,textWrap:"pretty"}}>{err}</div>}
    </div>
  );
}

function compress(file) {
  return new Promise(function(res) {
    var fr = new FileReader();
    fr.onload = function(ev) {
      var img = new Image();
      img.onload = function() {
        var rt = Math.min(900/img.width, 1);
        var cv = document.createElement("canvas");
        cv.width  = Math.round(img.width*rt);
        cv.height = Math.round(img.height*rt);
        cv.getContext("2d").drawImage(img, 0, 0, cv.width, cv.height);
        res(cv.toDataURL("image/jpeg", 0.75));
      };
      img.src = ev.target.result;
    };
    fr.readAsDataURL(file);
  });
}

